/* --- keyframes --- */
@keyframes festival-dragonboat-db-zongzi-sway {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(1.2px); }
}

@keyframes festival-dragonboat-db-drum-beat {
  0%, 100% { box-shadow: 0 2px 10px rgba(192, 57, 43, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.28); }
  30% { box-shadow: 0 3px 20px rgba(192, 57, 43, 0.68), 0 0 12px rgba(224, 169, 46, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.34); }
  55% { box-shadow: 0 2px 12px rgba(192, 57, 43, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.28); }
  80% { box-shadow: 0 3px 18px rgba(192, 57, 43, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.32); }
}

@keyframes festival-dragonboat-db-cord-flow {
  0% { background-position: center center, 0% 50%; }
  100% { background-position: center center, 300% 50%; }
}

@keyframes festival-dragonboat-db-night-zongzi-sway {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(1.2px); }
}

@keyframes festival-dragonboat-db-night-drum {
  0%, 100% { box-shadow: 0 2px 12px rgba(224, 82, 68, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.26); }
  30% { box-shadow: 0 3px 24px rgba(224, 82, 68, 0.75), 0 0 14px rgba(232, 187, 78, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.34); }
  55% { box-shadow: 0 2px 14px rgba(224, 82, 68, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.26); }
  80% { box-shadow: 0 3px 20px rgba(224, 82, 68, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.3); }
}

@keyframes festival-dragonboat-db-night-cord-flow {
  0% { background-position: center center, 0% 50%; }
  100% { background-position: center center, 300% 50%; }
}

/* --- signature palette repair (dsh-smkit port) ---
   The ten custom properties below were declared by the aionui-themes source
   outside the first :root block, which the dsh-themes converter dropped. Every
   var() reference resolved to guaranteed-invalid, so the whole declaration
   fell back to its initial value — the five-colour cord <hr>, the scrollbar
   and the primary button's lacquer gradient all painted nothing (white text on
   a transparent button). The values are reconstructed from the theme's own
   palette family to the converter-lost originals' intent: lacquer sits between
   the gradient's literal endpoints, the greens between brand and its light
   steps. (The full-viewport weave/wave overlays that also consumed them were
   removed above rather than repaired — see the note in the light decor block.) */
body[data-smkit-theme="festival-dragonboat"] {
  --db-lacquer: #c0392b;
  --db-leaf: #3f7d52;
  --db-leaf-vein: #6fa284;
  --db-mugwort: #7a9e6d;
  --db-river: #5b8a9c;
  --db-cord-red: #c0392b;
  --db-cord-yellow: #c98a1b;
  --db-cord-blue: #3a6fc4;
  --db-cord-green: #2e7d4f;
  --db-cord-white: #f2f0e3;
}

body[data-smkit-theme="festival-dragonboat"][data-ds-dark-theme] {
  --db-lacquer: #d94a3c;
  --db-leaf: #58a276;
  --db-leaf-vein: #8fc7a3;
  --db-mugwort: #93b586;
  --db-river: #7aa8bd;
  --db-cord-red: #e05244;
  --db-cord-yellow: #e0a92e;
  --db-cord-blue: #6f9be0;
  --db-cord-green: #58b386;
  --db-cord-white: #e6e2d0;
}

/* zcode — ZCode 桌面端配色原样移植 | light: #f8f8f8 会话画布、#ececee 窗口面
   侧栏、白色输入卡片、纯黑主按钮；dark: #161616 画布、#2b2b2b 侧栏、#2b2b2b
   输入卡片、纯白主按钮。色值取自 ZCode packages/ui/src/styles.css 的
   .theme-zai-light / .theme-zai-dark —— 桌面端实际渲染的是 zai 主题（实测
   会话区 #f8f8f8、侧栏 #ececee，与 @theme 默认块的 #fafafa/#f5f5f5 不同）。
   只写令牌：没有装饰层、没有字体、没有 markdown/pre 覆盖——这个文件没点名的
   表面（代码块在内）全部保持 DSH 原生。
   结构注记：静态刻度只写一份、明暗共用（00 最浅 → 1000 最深，与 DSH 自家
   静态刻度同向），昼夜间的一切差异走下面的 alias & specific 两块。dsh-themes
   的移植把深色刻度写成反向，深色画布因此吃到浅色槽位——这套不犯同样的错。 */

body[data-smkit-theme="zcode"] {
  color: #262626;
  background-color: #f8f8f8;
}

body[data-smkit-theme="zcode"][data-ds-dark-theme] {
  color: #d4d4d4;
  background-color: #161616;
}

/* --- static palette: shared by both modes --- */
body[data-smkit-theme="zcode"] {
  --dsw-static-deepseek-50: #f0f9ff;
  --dsw-static-blue-50: #f0f9ff;
  --dsw-static-deepseek-50p: #e0f2fe;
  --dsw-static-blue-50p: #e0f2fe;
  --dsw-static-deepseek-75: #e0f2fe;
  --dsw-static-blue-75: #e0f2fe;
  --dsw-static-deepseek-100: #e0f2fe;
  --dsw-static-blue-100: #e0f2fe;
  --dsw-static-deepseek-200: #bae6fd;
  --dsw-static-blue-200: #bae6fd;
  --dsw-static-deepseek-300: #7dd3fc;
  --dsw-static-blue-300: #7dd3fc;
  --dsw-static-deepseek-400: #38bdf8;
  --dsw-static-blue-400: #38bdf8;
  --dsw-static-deepseek-450: #38bdf8;
  --dsw-static-blue-450: #38bdf8;
  --dsw-static-deepseek-500: #0ea5e9;
  --dsw-static-blue-500: #0ea5e9;
  --dsw-static-deepseek-600: #0284c7;
  --dsw-static-blue-600: #0284c7;
  --dsw-static-deepseek-700-delete: #0369a1;
  --dsw-static-deepseek-800: #0369a1;
  --dsw-static-blue-800: #0369a1;
  --dsw-static-deepseek-900: #075985;
  --dsw-static-blue-900: #075985;
  --dsw-static-deepseek-950: #0c4a6e;
  --dsw-static-blue-950: #0c4a6e;
  /* Tailwind neutral，单方向：00 白 → 1000 近黑。深色画布由 DSH 的别名层取
     高位深槽（850–950 落在 #262626–#171717），浅色画布取低位浅槽（50–100 落在
     #fafafa/#f5f5f5）。ZCode 的中性阶本身不带蓝，bluish 与纯色同值。 */
  --dsw-static-neutral-bluish-00: #ffffff;
  --dsw-static-neutral-00: #ffffff;
  --dsw-static-neutral-bluish-50: #fafafa;
  --dsw-static-neutral-50: #fafafa;
  --dsw-static-neutral-bluish-60: #fafafa;
  --dsw-static-neutral-60: #fafafa;
  --dsw-static-neutral-bluish-75: #f5f5f5;
  --dsw-static-neutral-75: #f5f5f5;
  --dsw-static-neutral-bluish-100: #f5f5f5;
  --dsw-static-neutral-100: #f5f5f5;
  --dsw-static-neutral-bluish-150: #f0f0f0;
  --dsw-static-neutral-150: #f0f0f0;
  --dsw-static-neutral-bluish-200: #e5e5e5;
  --dsw-static-neutral-200: #e5e5e5;
  --dsw-static-neutral-bluish-250: #d4d4d4;
  --dsw-static-neutral-250: #d4d4d4;
  --dsw-static-neutral-bluish-300: #d4d4d4;
  --dsw-static-neutral-300: #d4d4d4;
  --dsw-static-neutral-bluish-400: #a3a3a3;
  --dsw-static-neutral-400: #a3a3a3;
  --dsw-static-neutral-bluish-500: #737373;
  --dsw-static-neutral-500: #737373;
  --dsw-static-neutral-bluish-550: #525252;
  --dsw-static-neutral-550: #525252;
  --dsw-static-neutral-bluish-600: #525252;
  --dsw-static-neutral-600: #525252;
  --dsw-static-neutral-bluish-700: #404040;
  --dsw-static-neutral-700: #404040;
  --dsw-static-neutral-bluish-750: #404040;
  --dsw-static-neutral-750: #404040;
  --dsw-static-neutral-bluish-800: #262626;
  --dsw-static-neutral-800: #262626;
  --dsw-static-neutral-bluish-850: #212121;
  --dsw-static-neutral-850: #212121;
  --dsw-static-neutral-bluish-875: #1a1a1a;
  --dsw-static-neutral-875: #1a1a1a;
  --dsw-static-neutral-bluish-900: #171717;
  --dsw-static-neutral-900: #171717;
  --dsw-static-neutral-bluish-950: #171717;
  --dsw-static-neutral-950: #171717;
  --dsw-static-neutral-bluish-1000: #0a0a0a;
  --dsw-static-neutral-1000: #0a0a0a;
  /* ZCode 语义色：green-600 / amber-600 / red-600 */
  --dsw-static-green-50: color-mix(in srgb, #16a34a 10%, white);
  --dsw-static-green-100: color-mix(in srgb, #16a34a 20%, white);
  --dsw-static-green-400: #16a34a;
